local MoneyCache = {}

local function getWallet()
    local player = Game:getPlayer()
    if player then
        return player:getWallet()
    end
    return nil
end

PlayerWallet = {}

function PlayerWallet:destroy()
    MoneyCache = {}
end

---设置自定义货币当前数量，可用于PayHelper检测货币是否足够
function PlayerWallet:setMoneyCount(coinId, count)
    MoneyCache[coinId] = count
end

---通过货币类型获取货币数量，查询不到返回9999999999
function PlayerWallet.getMoneyByCoinId(coinId)
    if coinId < CurrencyId.Currency then
        return MoneyCache[coinId] or 0
    end
    if coinId == CurrencyId.Currency then
        local wallet = getWallet()
        return wallet and math.max(wallet:getMoneyByCoinId(coinId), 0) or 0
    end
    return MoneyCache[coinId] or 9999999999
end

function PlayerWallet.getGolds()
    return MoneyCache[CurrencyId.Golds] or 0
end

function PlayerWallet.getDiamondsBlues()
    return MoneyCache[CurrencyId.Diamonds] or 0
end

function PlayerWallet.getDiamondsGolds()
    return MoneyCache[CurrencyId.Diamonds] or 0
end

function PlayerWallet.getCurrency()
    local wallet = getWallet()
    return wallet and math.max(wallet:getMoneyByCoinId(CurrencyId.Currency), 0) or 0
end

function PlayerWallet.getCoinNum(coinId)
    local wallet = getWallet()
    if wallet then
        return wallet:getCoinNum(coinId)
    end
    return 0
end